import { Box, Paper, Typography } from "@mui/material";
import { useEffect, useState } from "react"
import callApi from "../../Services/callApi";
import Swal from "sweetalert2";
import NurseActionButtons from "./NurseActionButtons";

export default function NurseList (){
    
    const [items,setItems] = useState<any[]>([]);
    useEffect(()=>{
        onLoadItem();
    },[])
    const onLoadItem = async ()=>{
        const res = await callApi('initial_treatment_record?type=list');
        if(res.data?.status=='success'){
            setItems(res.data?.data)
        }else{
            Swal.fire('Error',res?.data?.message,'error');
        }
    }
    return <>
        <FlashList items={items} />
        <NurseActionButtons />
    </>
}

const FlashList = ({ items }: any) => {
    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
            {items.map((item: any) => (
                <Paper key={item.id} sx={{ padding: 2, borderRadius: '16px', backgroundColor: 'white', boxShadow: '0 4px 8px rgba(0, 0, 0, 0.1)', display: 'flex', alignItems: 'center' }}>
                    <img src={'./user.png'} alt={item.fullname} style={{ width: '50px', height: '50px', marginRight: '16px', borderRadius: '8px' }} />
                    <Box sx={{textAlign:'left',color:'gray'}}>
                        <Typography variant="h6" sx={{ fontWeight: 'bold' }}>{item.fullname}</Typography>
                        <Typography variant="body2">Department: {item.department} {item.position}</Typography>
                        <Typography variant="body2">Position: {item.position}</Typography>
                        {/* <Typography variant="body2">Significant characteristic: {item.significant_characteristic}</Typography> */}
                        <Typography variant="body2">Date Time: {item.create_at}</Typography>
                    </Box>
                </Paper>
            ))}
        </Box>
    );
};
